-- The controller's verified evidence is provisioned by a trusted operator.
-- An app role, an intake receipt and an aal2 session cannot create evidence.
create table app_private.privacy_identity_attestations (
  id uuid primary key default gen_random_uuid(),
  request_id uuid not null references public.privacy_requests(id),
  subject_id uuid not null references auth.users(id),
  audience text not null check (audience in ('member', 'guest')),
  scope_id uuid not null,
  verification_reference text not null check (verification_reference ~ '^[a-zA-Z0-9][a-zA-Z0-9._:/-]{0,119}$'),
  verified_at timestamptz not null,
  expires_at timestamptz not null,
  revoked_at timestamptz,
  check (isfinite(verified_at) and isfinite(expires_at) and expires_at > verified_at)
);
create index privacy_identity_attestation_request on app_private.privacy_identity_attestations(request_id, verified_at desc, id);

create table app_private.privacy_fulfillments (
  request_id uuid not null references public.privacy_requests(id),
  request_version integer not null check (request_version > 0),
  attestation_id uuid not null references app_private.privacy_identity_attestations(id),
  prepared_by uuid not null references public.term_memberships(id),
  prepared_actor uuid not null references auth.users(id),
  prepared_at timestamptz not null default statement_timestamp(),
  source_hash text not null check (source_hash ~ '^[a-f0-9]{64}$'),
  correction_field text,
  correction_value text check (length(correction_value) <= 1000),
  approved_by uuid references public.term_memberships(id),
  approved_actor uuid references auth.users(id),
  approved_at timestamptz,
  release_hash text check (release_hash ~ '^[a-f0-9]{64}$'),
  primary key (request_id, request_version),
  check (correction_field is not null or correction_value is null),
  check (num_nonnulls(approved_by, approved_actor, approved_at, release_hash) in (0, 4)),
  check (approved_by <> prepared_by and approved_actor <> prepared_actor)
);
alter table app_private.privacy_identity_attestations enable row level security;
alter table app_private.privacy_identity_attestations force row level security;
alter table app_private.privacy_fulfillments enable row level security;
alter table app_private.privacy_fulfillments force row level security;
revoke all on app_private.privacy_identity_attestations, app_private.privacy_fulfillments from public, anon, authenticated, service_role;

alter table public.privacy_requests drop constraint privacy_requests_state_check,
  add constraint privacy_requests_state_check check (state in ('received','identity_check','in_review','referred','fulfilled'));
alter table public.privacy_events drop constraint privacy_events_operation_check,
  add constraint privacy_events_operation_check check (operation in (
    'notice_ack','request_create','request_list','request_read','request_review','queue_read',
    'retention_read','hold_create','hold_release','emergency_request','emergency_review','fulfillment_prepare','fulfillment_release'
  ));

create function app_private.protect_privacy_fulfillment() returns trigger language plpgsql set search_path = '' as $$
begin
  if tg_op = 'UPDATE' then
    if tg_table_name = 'privacy_identity_attestations' then
      if old.revoked_at is null and new.revoked_at is not null
        and to_jsonb(old) - 'revoked_at' = to_jsonb(new) - 'revoked_at' then return new; end if;
    elsif old.approved_at is null and new.approved_at is not null
      and to_jsonb(old) - array['approved_by','approved_actor','approved_at','release_hash']
        = to_jsonb(new) - array['approved_by','approved_actor','approved_at','release_hash'] then return new;
    end if;
  end if;
  raise exception using errcode = '55000', message = 'command_submitted_immutable';
end;
$$;
create trigger immutable_privacy_attestation before update or delete on app_private.privacy_identity_attestations
  for each row execute function app_private.protect_privacy_fulfillment();
create trigger immutable_privacy_fulfillment before update or delete on app_private.privacy_fulfillments
  for each row execute function app_private.protect_privacy_fulfillment();
create trigger immutable_fulfilled_privacy_request before update on public.privacy_requests
  for each row when (old.state = 'fulfilled') execute function app_private.request_history_guard();

create function app_private.privacy_profile_source(q public.privacy_requests, a app_private.privacy_identity_attestations)
returns jsonb language plpgsql stable security definer set search_path = '' as $$
declare snapshot jsonb;
begin
  if a.request_id is distinct from q.id or a.subject_id is distinct from q.subject_id
    or a.verified_at > statement_timestamp() or a.expires_at <= statement_timestamp() or a.revoked_at is not null
    or not exists (
      select 1 from public.terms t join public.organizations o on o.id = t.organization_id
      where t.id = q.term_id and t.state in ('active','frozen') and o.state = 'active'
        and (statement_timestamp() at time zone 'Asia/Manila')::date between t.starts_on and t.closes_on
    ) then return null; end if;

  if a.audience = 'member' then
    select jsonb_build_object('scopeId', tm.id, 'memberId', m.id, 'organizationId', m.organization_id,
      'version', coalesce(p.version, 0),
      'values', jsonb_build_object('displayName', m.display_name, 'course', p.course, 'yearLevel', p.year_level,
        'phone', p.phone, 'externalContact', p.external_contact, 'skills', p.skills,
        'pronunciation', p.pronunciation, 'affiliation', tm.affiliation_tag),
      'sharing', jsonb_build_object('course', coalesce(p.share_course, false), 'yearLevel', coalesce(p.share_year_level, false),
        'phone', coalesce(p.share_phone, false), 'externalContact', coalesce(p.share_external_contact, false),
        'skills', coalesce(p.share_skills, false), 'pronunciation', coalesce(p.share_pronunciation, false),
        'affiliation', coalesce(p.share_affiliation, false)))
    into snapshot
    from public.term_memberships tm
    join public.members m on m.id = tm.member_id and m.organization_id = tm.organization_id
    join auth.users u on u.id = m.auth_user_id and lower(btrim(u.email)) = m.normalized_email
    left join public.private_profiles p on p.member_id = m.id
    where tm.id = a.scope_id and tm.term_id = q.term_id and u.id = q.subject_id
      and app_private.is_school_identity(u.id) and m.account_state = 'active'
      and tm.membership_kind = 'core' and tm.status = 'active'
      and tm.joined_at <= statement_timestamp() and tm.ends_at > statement_timestamp()
      and exists (
        select 1 from app_private.effective_role_assignments r
        join public.role_permissions rp on rp.role_id = r.role_id and rp.term_id = r.term_id and rp.allowed_scope = r.scope_type
        where r.term_membership_id = tm.id and r.term_id = tm.term_id and r.scope_type = 'term' and rp.capability = 'workspace.read'
      );
  else
    select jsonb_build_object('scopeId', i.id, 'version', coalesce(p.version, 0),
      'values', jsonb_build_object('displayName', p.display_name, 'contactRoute', p.contact_route),
      'sharing', '{}'::jsonb)
    into snapshot
    from public.guest_invitations i left join public.guest_contact_profiles p on p.user_id = i.redeemed_by
    where i.id = a.scope_id and i.term_id = q.term_id and i.redeemed_by = q.subject_id
      and i.email = app_private.verified_google_email(q.subject_id)
      and i.revoked_at is null and i.expires_at > statement_timestamp()
      and app_private.active_guest_sponsor(i.sponsor_id);
  end if;
  return snapshot;
end;
$$;

create function app_private.privacy_profile_hash(p jsonb) returns text
language sql immutable strict set search_path = '' as $$
  select encode(sha256(convert_to(p::text, 'UTF8')), 'hex')
$$;

create function app_private.apply_privacy_profile_correction(
  q public.privacy_requests, a app_private.privacy_identity_attestations, p jsonb, field text, value text
) returns void language plpgsql security definer set search_path = '' as $$
declare member_id uuid := (p->>'memberId')::uuid;
begin
  if a.audience = 'guest' then
    insert into public.guest_contact_profiles(user_id, display_name, contact_route)
    values (q.subject_id, case when field = 'displayName' then value end, case when field = 'contactRoute' then value end)
    on conflict (user_id) do update set
      display_name = case when field = 'displayName' then excluded.display_name else guest_contact_profiles.display_name end,
      contact_route = case when field = 'contactRoute' then excluded.contact_route else guest_contact_profiles.contact_route end;
  elsif field = 'affiliation' then
    update public.term_memberships set affiliation_tag = value where id = a.scope_id;
    -- The ordinary profile editor uses this version for both shared and term fields.
    insert into public.private_profiles(member_id, organization_id)
    values (member_id, (p->>'organizationId')::uuid)
    on conflict on constraint private_profiles_pkey do update set course = private_profiles.course;
  else
    insert into public.private_profiles(member_id, organization_id, course, year_level, phone, external_contact, skills, pronunciation)
    values (member_id, (p->>'organizationId')::uuid,
      case when field = 'course' then value end, case when field = 'yearLevel' then value end,
      case when field = 'phone' then value end, case when field = 'externalContact' then value end,
      case when field = 'skills' then value end, case when field = 'pronunciation' then value end)
    on conflict on constraint private_profiles_pkey do update set
      course = case when field = 'course' then excluded.course else private_profiles.course end,
      year_level = case when field = 'yearLevel' then excluded.year_level else private_profiles.year_level end,
      phone = case when field = 'phone' then excluded.phone else private_profiles.phone end,
      external_contact = case when field = 'externalContact' then excluded.external_contact else private_profiles.external_contact end,
      skills = case when field = 'skills' then excluded.skills else private_profiles.skills end,
      pronunciation = case when field = 'pronunciation' then excluded.pronunciation else private_profiles.pronunciation end;
  end if;
end;
$$;

create function app_private.privacy_fulfillment_actor(p_term uuid, p_write boolean)
returns public.term_memberships language plpgsql stable security definer set search_path = '' as $$
declare m public.term_memberships;
begin
  m := app_private.request_actor(p_term, p_write);
  if not app_private.privacy_custodian(p_term) or not app_private.privacy_strong_session() then
    raise exception using errcode = '42501', message = 'command_permission_denied';
  end if;
  if app_private.disposition_replay_required(p_term) then
    raise exception using errcode = '55000', message = 'privacy_restore_replay_required';
  end if;
  return m;
end;
$$;

create function app_private.privacy_fulfillment_custody(p_term uuid, membership uuid, actor uuid)
returns boolean language sql stable security definer set search_path = '' as $$
  select app_private.privacy_custodian_live(p_term, membership) and exists (
    select 1 from public.term_memberships tm join public.members m on m.id = tm.member_id
    join auth.users u on u.id = m.auth_user_id and lower(btrim(u.email)) = m.normalized_email
    where tm.id = membership and tm.term_id = p_term and u.id = actor and app_private.is_school_identity(u.id)
  )
$$;

create function public.prepare_privacy_fulfillment(
  p_term_id uuid, p_privacy_request_id uuid, p_expected_version integer, p_request_id uuid,
  p_correction_field text default null, p_correction_value text default null
) returns jsonb language plpgsql security definer set search_path = '' as $$
declare q public.privacy_requests; a app_private.privacy_identity_attestations; m public.term_memberships;
  profile jsonb; payload jsonb; receipt jsonb; corrected text := nullif(btrim(p_correction_value), ''); max_length integer;
begin
  perform app_private.readiness_lock(p_term_id);
  m := app_private.privacy_fulfillment_actor(p_term_id, true);
  select * into q from public.privacy_requests where id = p_privacy_request_id and term_id = p_term_id for update;
  if not found or q.subject_id = auth.uid() then raise exception using errcode = '42501', message = 'command_permission_denied'; end if;
  payload := jsonb_build_array(p_term_id, q.id, p_expected_version, p_correction_field, p_correction_value);
  receipt := app_private.begin_work_command('prepare_privacy_fulfillment', p_request_id, payload);
  if receipt is not null then return receipt; end if;
  if q.version is distinct from p_expected_version then raise exception using errcode = '40001', message = 'command_stale_version'; end if;
  if q.state <> 'in_review' or q.kind not in ('access','export','correction')
    or exists (select 1 from app_private.privacy_fulfillments where request_id = q.id and request_version = q.version) then
    raise exception using errcode = '55000', message = 'command_dependency_blocked';
  end if;
  select * into a from app_private.privacy_identity_attestations x
  where x.request_id = q.id and x.subject_id = q.subject_id and x.revoked_at is null
    and x.verified_at <= statement_timestamp() and x.expires_at > statement_timestamp()
  order by x.verified_at desc, x.id limit 1 for share;
  profile := app_private.privacy_profile_source(q, a);
  if profile is null then raise exception using errcode = '55000', message = 'privacy_identity_evidence_required'; end if;

  if q.kind = 'correction' then
    max_length := case
      when a.audience = 'guest' and p_correction_field = 'displayName' then 200
      when a.audience = 'guest' and p_correction_field = 'contactRoute' then 320
      when a.audience = 'member' and p_correction_field in ('course','pronunciation') then 200
      when a.audience = 'member' and p_correction_field = 'externalContact' then 320
      when a.audience = 'member' and p_correction_field = 'skills' then 1000
      when a.audience = 'member' and p_correction_field in ('yearLevel','phone','affiliation') then 80
    end;
    if max_length is null or length(corrected) > max_length
      or corrected is not distinct from profile->'values'->>p_correction_field then
      raise exception using errcode = '22023', message = 'command_validation_failed';
    end if;
  elsif p_correction_field is not null or p_correction_value is not null then
    raise exception using errcode = '22023', message = 'command_validation_failed';
  end if;

  insert into app_private.privacy_fulfillments(
    request_id, request_version, attestation_id, prepared_by, prepared_actor, source_hash, correction_field, correction_value
  ) values (q.id, q.version, a.id, m.id, auth.uid(), app_private.privacy_profile_hash(profile), p_correction_field, corrected);
  return app_private.privacy_finish(p_term_id, 'prepare_privacy_fulfillment', p_request_id, payload,
    jsonb_build_object('version', q.version), q.id, 'request', 'fulfillment_prepare');
end;
$$;

create function public.approve_privacy_fulfillment(
  p_term_id uuid, p_privacy_request_id uuid, p_expected_version integer, p_review_hash text, p_request_id uuid
) returns jsonb language plpgsql security definer set search_path = '' as $$
declare q public.privacy_requests; a app_private.privacy_identity_attestations; f app_private.privacy_fulfillments;
  m public.term_memberships; profile jsonb; payload jsonb; receipt jsonb;
begin
  perform app_private.readiness_lock(p_term_id);
  m := app_private.privacy_fulfillment_actor(p_term_id, true);
  select * into q from public.privacy_requests where id = p_privacy_request_id and term_id = p_term_id for update;
  if not found or q.subject_id = auth.uid() then raise exception using errcode = '42501', message = 'command_permission_denied'; end if;
  payload := jsonb_build_array(p_term_id, q.id, p_expected_version, p_review_hash);
  receipt := app_private.begin_work_command('approve_privacy_fulfillment', p_request_id, payload);
  if receipt is not null then return receipt; end if;
  if q.version is distinct from p_expected_version then raise exception using errcode = '40001', message = 'command_stale_version'; end if;
  select * into f from app_private.privacy_fulfillments where request_id = q.id and request_version = q.version for update;
  if not found or q.state <> 'in_review' then raise exception using errcode = '55000', message = 'command_dependency_blocked'; end if;
  if f.prepared_actor = auth.uid() or f.prepared_by = m.id
    or not app_private.privacy_fulfillment_custody(p_term_id, f.prepared_by, f.prepared_actor) then
    raise exception using errcode = '42501', message = 'command_permission_denied';
  end if;
  if p_review_hash is distinct from app_private.privacy_profile_hash(to_jsonb(f)) then
    raise exception using errcode = '40001', message = 'command_stale_version';
  end if;
  select * into a from app_private.privacy_identity_attestations where id = f.attestation_id for share;
  if a.audience = 'member' then
    perform 1 from public.members where id = (select member_id from public.term_memberships where id = a.scope_id) for update;
  else
    perform 1 from auth.users where id = q.subject_id for update;
  end if;
  perform app_private.privacy_fulfillment_actor(p_term_id, true);
  profile := app_private.privacy_profile_source(q, a);
  if profile is null then raise exception using errcode = '55000', message = 'privacy_identity_evidence_required'; end if;
  if f.source_hash is distinct from app_private.privacy_profile_hash(profile) then
    raise exception using errcode = '40001', message = 'command_stale_version';
  end if;
  if q.kind = 'correction' then
    perform app_private.apply_privacy_profile_correction(q, a, profile, f.correction_field, f.correction_value);
    profile := app_private.privacy_profile_source(q, a);
  end if;
  update app_private.privacy_fulfillments set approved_by = m.id, approved_actor = auth.uid(),
    approved_at = statement_timestamp(), release_hash = app_private.privacy_profile_hash(profile)
  where request_id = q.id and request_version = q.version;
  update public.privacy_requests set state = 'fulfilled', version = version + 1, updated_at = statement_timestamp()
  where id = q.id returning * into q;
  return app_private.privacy_finish(p_term_id, 'approve_privacy_fulfillment', p_request_id, payload,
    jsonb_build_object('version', q.version), q.id, 'request', 'fulfillment_release');
end;
$$;

create function app_private.released_privacy_profile(q public.privacy_requests, f app_private.privacy_fulfillments)
returns jsonb language plpgsql stable security definer set search_path = '' as $$
declare a app_private.privacy_identity_attestations; profile jsonb;
begin
  if q.state <> 'fulfilled' or q.version <> f.request_version + 1 or f.approved_at is null
    or not app_private.privacy_fulfillment_custody(q.term_id, f.prepared_by, f.prepared_actor)
    or not app_private.privacy_fulfillment_custody(q.term_id, f.approved_by, f.approved_actor) then return null; end if;
  select * into a from app_private.privacy_identity_attestations where id = f.attestation_id;
  profile := app_private.privacy_profile_source(q, a);
  if f.release_hash is distinct from app_private.privacy_profile_hash(profile) then return null; end if;
  if q.kind = 'correction' then
    return jsonb_build_object('values', jsonb_build_object(f.correction_field, profile->'values'->f.correction_field), 'sharing', '{}'::jsonb);
  end if;
  return jsonb_build_object('values', profile->'values', 'sharing', profile->'sharing');
end;
$$;

create function public.read_privacy_fulfillment(p_term_id uuid, p_privacy_request_id uuid)
returns jsonb language plpgsql security definer set search_path = '' as $$
declare q public.privacy_requests; a app_private.privacy_identity_attestations; f app_private.privacy_fulfillments;
  profile jsonb; result jsonb;
begin
  perform app_private.privacy_subject(p_term_id);
  select * into q from public.privacy_requests where id = p_privacy_request_id and term_id = p_term_id;
  if not found or (q.subject_id <> auth.uid() and not app_private.privacy_custodian(p_term_id)) then
    perform app_private.record_content_read('read_privacy_fulfillment', p_term_id, null, false);
    return null;
  end if;

  if q.kind in ('access','export','correction') and q.state in ('in_review','fulfilled') then
    if q.subject_id = auth.uid() and q.state = 'in_review' then
      result := jsonb_build_object('status', 'waiting');
    elsif not app_private.privacy_strong_session() then
      result := jsonb_build_object('status', 'step_up');
    elsif q.state = 'fulfilled' then
      if q.subject_id = auth.uid() then
        select * into f from app_private.privacy_fulfillments where request_id = q.id and request_version = q.version - 1;
        profile := app_private.released_privacy_profile(q, f);
        result := jsonb_build_object('status', case when profile is null then 'paused' else 'released' end,
          'validUntil', (select expires_at from app_private.privacy_identity_attestations where id = f.attestation_id));
      else
        result := jsonb_build_object('status', 'finished');
      end if;
    else
      select * into f from app_private.privacy_fulfillments where request_id = q.id and request_version = q.version;
      if found then
        select * into a from app_private.privacy_identity_attestations where id = f.attestation_id;
      else
        select * into a from app_private.privacy_identity_attestations x
        where x.request_id = q.id and x.subject_id = q.subject_id and x.revoked_at is null
          and x.verified_at <= statement_timestamp() and x.expires_at > statement_timestamp()
        order by x.verified_at desc, x.id limit 1;
      end if;
      profile := app_private.privacy_profile_source(q, a);
      if f.request_id is not null and (
        f.source_hash is distinct from app_private.privacy_profile_hash(profile)
        or not app_private.privacy_fulfillment_custody(p_term_id, f.prepared_by, f.prepared_actor)
      ) then
        result := jsonb_build_object('status', 'stale');
      elsif profile is null then
        result := jsonb_build_object('status', 'identity_needed');
      else
        result := jsonb_build_object(
          'status', case when f.request_id is null then 'ready' else 'prepared' end, 'audience', a.audience,
          'verificationReference', a.verification_reference, 'validUntil', a.expires_at,
          'values', case when q.kind <> 'correction' then profile->'values' when f.correction_field is not null
            then jsonb_build_object(f.correction_field, profile->'values'->f.correction_field) else '{}'::jsonb end,
          'sharing', case when q.kind <> 'correction' then profile->'sharing' when profile->'sharing' ? f.correction_field
            then jsonb_build_object(f.correction_field, profile->'sharing'->f.correction_field) else '{}'::jsonb end,
          'correctionField', f.correction_field, 'correctionValue', f.correction_value,
          'canApprove', f.request_id is not null and f.prepared_actor <> auth.uid() and f.prepared_by <> public.current_term_membership(p_term_id),
          'reviewHash', case when f.request_id is not null then app_private.privacy_profile_hash(to_jsonb(f)) end
        );
      end if;
    end if;
  end if;
  perform app_private.record_content_read('read_privacy_fulfillment', p_term_id, q.id, result is not null);
  return result;
end;
$$;

create function app_private.privacy_response(p_term uuid, p_request uuid, p_export boolean)
returns jsonb language plpgsql security definer set search_path = '' as $$
declare q public.privacy_requests; f app_private.privacy_fulfillments; profile jsonb; expiry timestamptz;
begin
  perform app_private.privacy_subject(p_term);
  if not app_private.privacy_strong_session() then raise exception using errcode = '42501', message = 'command_permission_denied'; end if;
  select * into q from public.privacy_requests
  where id = p_request and term_id = p_term and subject_id = auth.uid() and state = 'fulfilled'
    and (case when p_export then kind = 'export' else kind in ('access','correction') end);
  if found then
    select * into f from app_private.privacy_fulfillments where request_id = q.id and request_version = q.version - 1;
    profile := app_private.released_privacy_profile(q, f);
    if profile is not null then
      select expires_at into expiry from app_private.privacy_identity_attestations where id = f.attestation_id;
    end if;
  end if;
  perform app_private.record_content_read(case when p_export then 'export_privacy_response' else 'read_privacy_response' end,
    p_term, q.id, profile is not null);
  if profile is null then return null; end if;
  return profile || jsonb_build_object('reference', q.reference, 'validUntil', expiry);
end;
$$;

create function public.read_privacy_response(p_term_id uuid, p_privacy_request_id uuid)
returns jsonb language sql security definer set search_path = '' as $$
  select app_private.privacy_response(p_term_id, p_privacy_request_id, false)
$$;
